import subprocess, random, re, itertools
random.seed(7)
cats=set(); order_viol=[]; xy_viol=[]
cases=[]
alphas=['','Q','QQ','z','a','é','\U0001F600','ab\ncd','0','  ','A'*30,'"',"'",'\\','\t','\x00' ]
for a in alphas:
    for b,c in [(0,0),(1,2),(-5,-5),(10**30,-10**30),(7,7),(2,1),(0,-0)]:
        cases.append((a,b,c))
for _ in range(40):
    cases.append((''.join(random.choice('Qq\n\t 0"\'\\') for _ in range(random.randint(0,4))), random.randint(-10**12,10**12), random.randint(-10**12,10**12)))
for a,b,c in cases:
    r=subprocess.run(['./test15_executable','--a',a,'--b',str(b),'--c',str(c)],capture_output=True,text=True)
    if r.returncode!=0: print('NONZERO',repr((a,b,c)),r.stderr[:200]); continue
    lines=r.stdout.split('\n')
    for idx in (0,3,5,8,9,10,11):
        L=lines[idx]
        for m in re.findall(r"'([a-z_]+)':", L):
            if m not in ('new_value','old_value','diff'): cats.add(m)
        if 'dictionary_item_added' in L and 'values_changed' in L:
            if L.index('dictionary_item_added')>L.index('values_changed'): order_viol.append((a,b,c,idx,L))
        if "root['x']" in L and "root['y']" in L:
            if L.index("root['x']")>L.index("root['y']"): xy_viol.append((a,b,c,idx,L))
print('cases run:',len(cases))
print('categories seen:',sorted(cats))
print('category-order violations:',order_viol[:3], len(order_viol))
print('x-before-y violations:',xy_viol[:3], len(xy_viol))
EOF

